draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw a book
  ctx.fillStyle = '#663300';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 75, 100, 150);
  ctx.stroke();

  // Draw a stick figure
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 80);
  ctx.lineTo(W/2, H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 - 30, H/2 - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2 + 30, H/2 - 40);
  ctx.stroke();

  // Draw a lightbulb above the stick figure's head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 150 + 20 * Math.sin(t), 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 150 + 20 * Math.sin(t));
  ctx.lineTo(W/2, H/2 - 120);
  ctx.stroke();

  // Draw a line from the book to the stick figure's hand
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 25);
  ctx.lineTo(W/2 - 30, H/2 - 40);
  ctx.stroke();

  ctx.restore();
}
